{
  "name": "WB FBS Scanner",
  "description": "Warehouse PWA for scanning Wildberries orders and linking 'Honest Sign' (KIZ) codes using hardware scanners."
}

export interface WBOrder {
  id: number; // Order ID (rid)
  stickerId: string; // The barcode string on the WB sticker
  article: string; // nmId or vendor code
  title: string;
  price: number;
  photoUrl: string;
  isSgtinRequired: boolean;
  sgtin?: string; // The linked KIZ
  status: 'pending' | 'done';
}

export interface SupplyStats {
  total: number;
  done: number;
}

export enum AppStep {
  LOGIN = 'LOGIN',
  SCAN_ORDER = 'SCAN_ORDER',
  SCAN_KIZ = 'SCAN_KIZ',
  SUCCESS_FEEDBACK = 'SUCCESS_FEEDBACK',
  ERROR_FEEDBACK = 'ERROR_FEEDBACK',
}

export interface AudioContextType {
  playSuccess: () => void;
  playDoubleSuccess: () => void;
  playError: () => void;
}

export interface ScanResult {
  success: boolean;
  message?: string;
  type?: 'ORDER' | 'KIZ';
  data?: any;
}

class AudioService {
  private ctx: AudioContext | null = null;

  constructor() {
    try {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      this.ctx = new AudioContextClass();
    } catch (e) {
      console.warn('Web Audio API not supported');
    }
  }

  private playTone(freq: number, type: OscillatorType, duration: number, startTime: number = 0) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, this.ctx.currentTime + startTime);

    gain.gain.setValueAtTime(0.1, this.ctx.currentTime + startTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + startTime + duration);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(this.ctx.currentTime + startTime);
    osc.stop(this.ctx.currentTime + startTime + duration);
  }

  // Short high beep for Order Scan
  public playScanSuccess() {
    if (this.ctx?.state === 'suspended') this.ctx.resume();
    this.playTone(1200, 'sine', 0.1);
  }

  // Double major beep for KIZ Link (Success)
  public playTaskComplete() {
    if (this.ctx?.state === 'suspended') this.ctx.resume();
    this.playTone(880, 'sine', 0.1, 0);       // A5
    this.playTone(1108, 'sine', 0.2, 0.15);   // C#6
  }

  // Low buzz for Error
  public playError() {
    if (this.ctx?.state === 'suspended') this.ctx.resume();
    this.playTone(150, 'sawtooth', 0.4);
  }
}

export const audioService = new AudioService();

import { WBOrder } from '../types';

const MOCK_DELAY = 500;

// Helper to generate a random large number string
const randId = () => Math.floor(Math.random() * 1000000000).toString();

export const demoOrders: WBOrder[] = Array.from({ length: 15 }).map((_, i) => ({
  id: parseInt(randId()),
  stickerId: `WB-${Math.floor(Math.random() * 1000)}`,
  article: `ART-${1000 + i}`,
  title: `Wildberries Product Test Item ${i + 1}`,
  price: Math.floor(Math.random() * 5000) + 500,
  photoUrl: `https://picsum.photos/400/500?random=${i}`,
  isSgtinRequired: true,
  status: 'pending'
}));

/**
 * Clean barcode string (remove surrounding *)
 */
export const cleanBarcode = (code: string): string => {
  return code.replace(/^\*+|\*+$/g, '').trim();
};

/**
 * Simulates the backend logic described in the prompt:
 * 1. GET Orders
 * 2. POST Orders/Stickers (to get barcodes)
 * 3. Merge and return
 */
export const fetchSupplyOrders = async (
  token: string, 
  supplyId: string, 
  isDemo: boolean
): Promise<{ orders: WBOrder[], map: Record<string, number> }> => {

  if (isDemo) {
    await new Promise(r => setTimeout(r, MOCK_DELAY));
    const map: Record<string, number> = {};
    demoOrders.forEach(o => {
      map[o.stickerId] = o.id;
      // Add a clean version to map just in case
      map[cleanBarcode(o.stickerId)] = o.id; 
    });
    return { orders: [...demoOrders], map };
  }

  // --- Real API Logic Implementation (Client-side proxy simulation) ---
  // In a real scenario, this code would likely run on a Next.js server to avoid CORS
  // and hide header logic. Here we implement the fetches as requested.

  try {
    const headers = {
      'Authorization': token,
      'Content-Type': 'application/json',
      'Accept': 'application/json'
    };

    // 1. Get Orders
    const ordersUrl = `https://marketplace-api.wildberries.ru/api/v3/supplies/${supplyId}/orders`;
    const ordersRes = await fetch(ordersUrl, { headers });

    if (!ordersRes.ok) throw new Error(`Failed to fetch orders: ${ordersRes.statusText}`);
    const ordersData = await ordersRes.json();
    const rawOrders = ordersData.orders || [];

    if (rawOrders.length === 0) {
      return { orders: [], map: {} };
    }

    const orderIds = rawOrders.map((o: any) => o.id);

    // 2. Get Stickers (Chunked 100)
    // Simplified for this demo to take first 100 if many
    const chunkIds = orderIds.slice(0, 100); 
    const stickersUrl = `https://marketplace-api.wildberries.ru/api/v3/orders/stickers?type=svg&width=58&height=40`;

    const stickersRes = await fetch(stickersUrl, {
      method: 'POST',
      headers,
      body: JSON.stringify({ orders: chunkIds })
    });

    if (!stickersRes.ok) throw new Error(`Failed to fetch stickers: ${stickersRes.statusText}`);
    const stickersData = await stickersRes.json();
    const stickers = stickersData.data || [];

    // 3. Merge Data
    const mergedOrders: WBOrder[] = [];
    const barcodeMap: Record<string, number> = {};

    rawOrders.forEach((ro: any) => {
      // Find sticker data
      const stickerObj = stickers.find((s: any) => s.orderId === ro.id);

      // In reality, you'd decode the base64 SVG or barcode value from the sticker data
      // API v3 stickers endpoint returns partA + partB which form the code.
      // For this PWA implementation, we assume we can extract the 'barcode' string.
      // NOTE: WB V3 Stickers endpoint returns SVG base64. 
      // Parsing barcode from SVG client side is hard. 
      // USUALLY the sticker ID (partA + partB) matches the barcode text.

      // Fallback logic for this exercise: assuming 'wbStickerIdParts' or similar exists,
      // or we construct it. Let's assume partA + partB as string.
      const stickerCode = stickerObj ? `${stickerObj.partA}${stickerObj.partB}` : `UNKNOWN-${ro.id}`;

      // Image Logic (Basket URL generation is complex, using placeholder for safety)
      const photoUrl = `https://picsum.photos/400/400?seed=${ro.id}`; 

      const order: WBOrder = {
        id: ro.id,
        stickerId: stickerCode,
        article: ro.nmId ? ro.nmId.toString() : 'N/A',
        title: `WB Item ${ro.nmId}`, // Title usually requires another fetch to content API
        price: ro.convertedPrice ? ro.convertedPrice / 100 : 0,
        photoUrl,
        isSgtinRequired: true, // Assuming all in this supply need it
        status: 'pending'
      };

      mergedOrders.push(order);
      barcodeMap[stickerCode] = ro.id;
      barcodeMap[cleanBarcode(stickerCode)] = ro.id;
    });

    return { orders: mergedOrders, map: barcodeMap };

  } catch (err: any) {
    console.error(err);
    throw new Error(err.message || "API Error");
  }
};

/**
 * Links KIZ (SGTIN) to an Order
 */
export const linkKizToOrder = async (
  token: string, 
  orderId: number, 
  kiz: string, 
  isDemo: boolean
): Promise<boolean> => {
  if (isDemo) {
    await new Promise(r => setTimeout(r, MOCK_DELAY));
    return true;
  }

  try {
    const url = `https://marketplace-api.wildberries.ru/api/v3/orders/${orderId}/meta/sgtin`;
    const res = await fetch(url, {
      method: 'PUT',
      headers: {
        'Authorization': token,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ sgtins: [kiz] })
    });

    if (!res.ok) throw new Error("Failed to link SGTIN");
    return true;
  } catch (e) {
    console.error(e);
    return false;
  }
};

import React, { useEffect, useRef, useState } from 'react';

interface ScannerInputProps {
  onScan: (code: string) => void;
  isDisabled?: boolean;
}

export const ScannerInput: React.FC<ScannerInputProps> = ({ onScan, isDisabled }) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [buffer, setBuffer] = useState('');

  // Keep focus alive
  useEffect(() => {
    const focusInput = () => {
      if (!isDisabled && inputRef.current) {
        inputRef.current.focus();
      }
    };

    const interval = setInterval(focusInput, 2000);
    window.addEventListener('click', focusInput);
    focusInput();

    return () => {
      clearInterval(interval);
      window.removeEventListener('click', focusInput);
    };
  }, [isDisabled]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      if (buffer.trim().length > 0) {
        onScan(buffer.trim());
        setBuffer('');
      }
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setBuffer(e.target.value);
  };

  return (
    <div className="absolute top-0 left-0 w-0 h-0 overflow-hidden opacity-0">
      <input
        ref={inputRef}
        type="text"
        value={buffer}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        autoComplete="off"
        disabled={isDisabled}
      />
    </div>
  );
};

import React from 'react';

interface Props {
  status: 'SUCCESS' | 'ERROR' | null;
  message?: string;
}

export const ScanOverlay: React.FC<Props> = ({ status, message }) => {
  if (!status) return null;

  const bgClass = status === 'SUCCESS' 
    ? 'bg-green-500/90 animate-flash-green' 
    : 'bg-red-600/90 animate-pulse';

  const icon = status === 'SUCCESS' ? (
    <svg className="w-24 h-24 text-white mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
    </svg>
  ) : (
    <svg className="w-24 h-24 text-white mb-4 animate-shake" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
    </svg>
  );

  return (
    <div className={`fixed inset-0 z-50 flex flex-col items-center justify-center text-center p-6 ${bgClass} transition-all duration-300`}>
      {icon}
      {message && (
        <h2 className="text-3xl font-bold text-white uppercase tracking-wider drop-shadow-md">
          {message}
        </h2>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { WBOrder, AppStep, SupplyStats } from './types';
import { fetchSupplyOrders, linkKizToOrder, cleanBarcode } from './services/wbService';
import { audioService } from './services/audioService';
import { ScannerInput } from './components/ScannerInput';
import { ScanOverlay } from './components/ScanOverlay';
import { Settings, Package, QrCode, LogOut, CheckCircle, Barcode, WifiOff, Loader2 } from 'lucide-react';

const App: React.FC = () => {
  // --- State ---
  const [token, setToken] = useState('');
  const [supplyId, setSupplyId] = useState('');
  const [isDemo, setIsDemo] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const [step, setStep] = useState<AppStep>(AppStep.LOGIN);
  const [orders, setOrders] = useState<WBOrder[]>([]);
  const [orderMap, setOrderMap] = useState<Record<string, number>>({});
  const [activeOrder, setActiveOrder] = useState<WBOrder | null>(null);

  // Feedback State
  const [overlayStatus, setOverlayStatus] = useState<'SUCCESS' | 'ERROR' | null>(null);
  const [feedbackMsg, setFeedbackMsg] = useState('');

  // Wake Lock Ref
  const wakeLockRef = useRef<WakeLockSentinel | null>(null);

  // --- Effects ---

  // Request Wake Lock on mount (if supported)
  useEffect(() => {
    const requestWakeLock = async () => {
      try {
        if ('wakeLock' in navigator) {
          wakeLockRef.current = await navigator.wakeLock.request('screen');
        }
      } catch (err) {
        console.warn('Wake Lock failed', err);
      }
    };
    if (step !== AppStep.LOGIN) requestWakeLock();
    return () => {
      wakeLockRef.current?.release();
    };
  }, [step]);

  // --- Helpers ---

  const showFeedback = (type: 'SUCCESS' | 'ERROR', msg: string, duration = 1500) => {
    setOverlayStatus(type);
    setFeedbackMsg(msg);
    if (type === 'SUCCESS') {
      if (step === AppStep.SCAN_KIZ) audioService.playTaskComplete();
      else audioService.playScanSuccess();
    } else {
      audioService.playError();
    }

    setTimeout(() => {
      setOverlayStatus(null);
      setFeedbackMsg('');
      if (type === 'SUCCESS' && step === AppStep.SCAN_KIZ) {
        // Reset to waiting for next order
        setStep(AppStep.SCAN_ORDER);
        setActiveOrder(null);
      }
    }, duration);
  };

  const getStats = (): SupplyStats => {
    return {
      total: orders.length,
      done: orders.filter(o => o.status === 'done').length
    };
  };

  // --- Handlers ---

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!token && !isDemo) return setErrorMsg("API Token Required");
    if (!supplyId && !isDemo) return setErrorMsg("Supply ID Required");

    setIsLoading(true);
    setErrorMsg(null);

    try {
      const data = await fetchSupplyOrders(token, supplyId, isDemo);
      setOrders(data.orders);
      setOrderMap(data.map);
      setStep(AppStep.SCAN_ORDER);
    } catch (err: any) {
      setErrorMsg(err.message || "Failed to load supply");
    } finally {
      setIsLoading(false);
    }
  };

  const handleScan = async (rawCode: string) => {
    if (overlayStatus !== null || isLoading) return; // Block input during feedback or loading

    const code = cleanBarcode(rawCode);
    console.log("Scanned:", code, "Current Step:", step);

    // --- LOGIC: WAITING FOR ORDER (QR) ---
    if (step === AppStep.SCAN_ORDER) {
      const orderId = orderMap[code];

      if (!orderId) {
        showFeedback('ERROR', 'Order Not Found');
        return;
      }

      const order = orders.find(o => o.id === orderId);
      if (!order) return;

      if (order.status === 'done') {
        showFeedback('ERROR', 'Already Packed');
        return;
      }

      // Found valid order
      setActiveOrder(order);
      setStep(AppStep.SCAN_KIZ);
      audioService.playScanSuccess();
      return;
    }

    // --- LOGIC: WAITING FOR KIZ (DataMatrix) ---
    if (step === AppStep.SCAN_KIZ && activeOrder) {
      // Validation 1: Prevent scanning the WB QR again
      if (orderMap[code]) {
         showFeedback('ERROR', 'Scan KIZ, not WB Sticker');
         return;
      }

      // Validation 2: KIZ Length (DataMatrix usually long)
      if (code.length < 10) {
        showFeedback('ERROR', 'Invalid KIZ Format');
        return;
      }

      // Perform Link
      setIsLoading(true);
      const success = await linkKizToOrder(token, activeOrder.id, code, isDemo);
      setIsLoading(false);

      if (success) {
        // Update local state
        setOrders(prev => prev.map(o => o.id === activeOrder.id ? { ...o, status: 'done', sgtin: code } : o));
        showFeedback('SUCCESS', 'Linked Successfully', 1000);
        // Step reset happens in showFeedback timeout
      } else {
        showFeedback('ERROR', 'API Link Failed');
      }
    }
  };

  // --- Renderers ---

  if (step === AppStep.LOGIN) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col justify-center items-center p-4">
        <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-8">
          <div className="flex justify-center mb-6">
            <div className="bg-wb-brand p-4 rounded-full">
              <Package className="w-10 h-10 text-white" />
            </div>
          </div>
          <h1 className="text-2xl font-bold text-center text-wb-dark mb-2">WB FBS Scanner</h1>
          <p className="text-gray-500 text-center mb-8">Link Honest Sign (KIZ) to Orders</p>

          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">API Token</label>
              <input
                type="password"
                className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-wb-brand focus:border-wb-brand outline-none transition-all"
                placeholder="Paste v3 API token"
                value={token}
                onChange={e => setToken(e.target.value)}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Supply ID</label>
              <input
                type="text"
                className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-wb-brand focus:border-wb-brand outline-none transition-all"
                placeholder="WB-GI-xxxxxxx"
                value={supplyId}
                onChange={e => setSupplyId(e.target.value)}
              />
            </div>

            <div className="flex items-center space-x-3 py-2">
              <button 
                type="button" 
                onClick={() => setIsDemo(!isDemo)}
                className={`flex-1 py-2 px-4 rounded border text-sm font-medium transition-colors ${isDemo ? 'bg-indigo-100 border-indigo-300 text-indigo-700' : 'bg-gray-100 border-gray-300 text-gray-600'}`}
              >
                Demo Mode: {isDemo ? 'ON' : 'OFF'}
              </button>
            </div>

            {errorMsg && (
              <div className="p-3 rounded bg-red-50 text-red-600 text-sm flex items-center">
                <WifiOff className="w-4 h-4 mr-2" />
                {errorMsg}
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-4 bg-wb-brand hover:bg-fuchsia-700 text-white font-bold rounded-xl transition-all shadow-lg hover:shadow-xl disabled:opacity-70 flex justify-center items-center"
            >
              {isLoading ? <Loader2 className="animate-spin w-6 h-6" /> : "Load Orders"}
            </button>
          </form>
        </div>
      </div>
    );
  }

  // Work Stats
  const stats = getStats();
  const progress = stats.total > 0 ? (stats.done / stats.total) * 100 : 0;

  return (
    <div className="flex flex-col h-screen bg-gray-100">
      <ScannerInput onScan={handleScan} isDisabled={overlayStatus !== null} />
      <ScanOverlay status={overlayStatus} message={feedbackMsg} />

      {/* Header */}
      <header className="bg-white shadow-sm border-b px-4 py-3 z-10">
        <div className="flex justify-between items-center mb-2">
          <div className="flex items-center space-x-2">
            <span className="font-bold text-wb-dark text-lg">
              {stats.done} / {stats.total}
            </span>
            <span className="text-xs px-2 py-0.5 bg-gray-200 rounded text-gray-600 font-mono">
              {isDemo ? 'DEMO' : supplyId}
            </span>
          </div>
          <button onClick={() => setStep(AppStep.LOGIN)} className="text-gray-400 hover:text-red-500">
            <LogOut className="w-6 h-6" />
          </button>
        </div>
        {/* Progress Bar */}
        <div className="h-3 w-full bg-gray-200 rounded-full overflow-hidden">
          <div 
            className="h-full bg-green-500 transition-all duration-500 ease-out"
            style={{ width: `${progress}%` }}
          />
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col p-4 overflow-y-auto">

        {step === AppStep.SCAN_ORDER && (
          <div className="flex-1 flex flex-col justify-center items-center text-center space-y-6 animate-pulse-fast border-4 border-dashed border-state-idle rounded-3xl p-6 bg-blue-50">
            <div className="bg-white p-6 rounded-full shadow-lg">
               <QrCode className="w-24 h-24 text-state-idle" />
            </div>
            <div>
              <h2 className="text-3xl font-extrabold text-blue-900 mb-2">SCAN ORDER</h2>
              <p className="text-blue-600 text-lg">Scan the WB Sticker QR Code</p>
            </div>
            <div className="mt-8 opacity-50 text-sm">
              Keyboard input active
            </div>
          </div>
        )}

        {step === AppStep.SCAN_KIZ && activeOrder && (
          <div className="flex-1 flex flex-col border-4 border-solid border-state-kiz rounded-3xl overflow-hidden shadow-2xl bg-white relative">

            {/* Top Badge */}
            <div className="bg-state-kiz text-white text-center py-2 font-bold tracking-widest uppercase">
              Scan Honest Sign (KIZ)
            </div>

            <div className="flex-1 flex flex-col p-6">
              {/* Product Info */}
              <div className="flex space-x-4 mb-6">
                 <img 
                    src={activeOrder.photoUrl} 
                    alt="Product" 
                    className="w-32 h-40 object-cover rounded-lg shadow-md bg-gray-200"
                  />
                 <div className="flex-1 flex flex-col justify-between py-1">
                    <div>
                      <h3 className="font-bold text-gray-900 leading-tight mb-1 line-clamp-3 text-lg">
                        {activeOrder.title}
                      </h3>
                      <p className="text-sm text-gray-500">Art: {activeOrder.article}</p>
                    </div>
                    <div className="text-2xl font-bold text-wb-brand">
                      {activeOrder.price} ₽
                    </div>
                 </div>
              </div>

              <div className="flex-1 flex flex-col justify-center items-center text-center space-y-4">
                 <Barcode className="w-32 h-32 text-state-kiz opacity-80" />
                 <p className="text-purple-900 font-medium text-xl animate-pulse">
                   Waiting for DataMatrix...
                 </p>
              </div>
            </div>

            {/* Warning / Hint */}
            <div className="bg-purple-50 p-4 border-t border-purple-100 text-center text-purple-800 text-sm">
               Check the code length. Do not scan WB QR again.
            </div>
          </div>
        )}

      </main>

      {/* Footer / Status Bar */}
      <footer className="bg-white border-t p-3 text-center text-xs text-gray-400">
        Status: {isLoading ? 'Processing...' : 'Ready'} | Mode: {isDemo ? 'Simulation' : 'Live'}
      </footer>

    </div>
  );
};

export default App;

