export const fetchSupplyOrders = async (
  token: string, 
  supplyId: string, 
  isDemo: boolean
): Promise<{ orders: WBOrder[], map: Record<string, number> }> => {

  // Demo Mode - Client Side
  if (isDemo) {
    await new Promise(r => setTimeout(r, MOCK_DELAY));
    const map: Record<string, number> = {};
    demoOrders.forEach(o => {
      map[o.stickerId] = o.id;
      map[cleanBarcode(o.stickerId)] = o.id; 
    });
    return { orders: [...demoOrders], map };
  }

  // Real Mode - Call Vercel API Proxy
  try {
    const res = await fetch('/api/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token, supplyId })
    });

    if (!res.ok) {
      const errData = await res.json();
      throw new Error(errData.error || 'Failed to fetch supply orders');
    }

    const data = await res.json();

    // We need to ensure the map handles cleaned barcodes too
    // The API returns strict mapping, we enhance it here for usability
    const enhancedMap = { ...data.map };
    Object.keys(data.map).forEach(key => {
      enhancedMap[cleanBarcode(key)] = data.map[key];
    });

    return { orders: data.orders, map: enhancedMap };

  } catch (err: any) {
    console.error(err);
    throw new Error(err.message || "API Error");
  }
};

export const linkKizToOrder = async (
  token: string, 
  orderId: number, 
  kiz: string, 
  isDemo: boolean
): Promise<boolean> => {
  if (isDemo) {
    await new Promise(r => setTimeout(r, MOCK_DELAY));
    return true;
  }

  try {
    const res = await fetch('/api/bind', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token, orderId, kiz })
    });

    if (!res.ok) {
      console.error(await res.text());
      return false;
    }
    return true;
  } catch (e) {
    console.error(e);
    return false;
  }
};

