            {/* Main Scanner Input */}
            <ScannerInput 
              onScan={handleScan} 
              isDisabled={isLoading} 
              placeholder={
                activeOrder 
                ? ">>> СКАНИРУЙ КИЗ (DataMatrix) <<<" 
                : "1. Сканируй QR стикера WB..."
              }
            />

            {/* Instruction Text */}
            <div className="text-center text-gray-400 text-sm">
              {activeOrder 
                ? "Найдите квадратный код DataMatrix на упаковке товара" 
