        const photoUrl = matchingCard?.photos?.?.big || matchingCard?.photos?.?.tm || null;

        return {
          id: order.id,           // ID сборочного задания
          nmId: order.nmId,       // Артикул WB
          article: order.article, // Ваш артикул
          photo: photoUrl,        // Ссылка на фото
          rid: order.rid
        };
      });

      setOrders(mergedOrders);

    } catch (err) {
      console.error(err);
      setError('Ошибка загрузки данных. Проверьте консоль и CORS.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSupplyData();
  }, []);

  if (loading) return <div>Загрузка поставки...</div>;
  if (error) return <div style={{color: 'red'}}>{error}</div>;

  return (
    <div style={{ padding: 20 }}>
