      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 20 }}>
        {orders.map(order => (
          <div key={order.id} style={{ border: '1px solid #ccc', padding: 10, borderRadius: 8 }}>
            <div style={{ height: 200, background: '#f0f0f0', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 10 }}>
              {order.photo ? (
