Понял, переходим на React.
Поскольку Wildberries API разделен на разные хосты и требует разные токены, на фронтенде (React) вам придется агрегировать данные.
Ниже представлен пример компонента, который решает вашу задачу: берет ID поставки, вытягивает заказы (FBS API) и обогащает их фотографиями (Content API).
Основные нюансы для React + WB API:
1. CORS (Cross-Origin Resource Sharing): API Wildberries часто блокирует прямые запросы из браузера (localhost). Вам скорее всего понадобится Proxy (в vite.config.js или package.json) или небольшой backend-proxy. В примере код написан для прямого запроса, но держите это в уме.
2. Два токена: Вам понадобятся Marketplace Token (для заказов) и Content Token (для фото).
Реализация (React Hook)
import React, { useState, useEffect } from 'react';
import axios from 'axios'; // Рекомендую axios для удобства

const SUPPLY_ID = 'WB-GI-201752529'; // Ваш ID поставки
const MARKET_TOKEN = 'ВАШ_ТОКЕН_МАРКЕТПЛЕЙС';
const CONTENT_TOKEN = 'ВАШ_ТОКЕН_КОНТЕНТ';

const WbSupplyScanner = () => {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const fetchSupplyData = async () => {
    setLoading(true);
    setError(null);
    try {
      // ---------------------------------------------------------
      // ШАГ 1: Получаем ID заказов в поставке (Marketplace API)
      // ---------------------------------------------------------
      const idsResponse = await axios.get(
        `https://marketplace-api.wildberries.ru/api/marketplace/v3/supplies/${SUPPLY_ID}/order-ids`,
        { headers: { Authorization: MARKET_TOKEN } }
      );

      const orderIds = idsResponse.data.orderIds;
      if (!orderIds || orderIds.length === 0) {
        setOrders([]);
        return;
      }

      // ---------------------------------------------------------
      // ШАГ 2: Получаем детали заказов - nmId и артикулы (Marketplace API)
      // ---------------------------------------------------------
      const detailsResponse = await axios.post(
        'https://marketplace-api.wildberries.ru/api/v3/orders',
        { orders: orderIds },
        { headers: { Authorization: MARKET_TOKEN } }
      );

      const ordersData = detailsResponse.data.orders;

      // Собираем все nmId, чтобы запросить для них фото разом
      const nmIdsToFetch = ordersData.map(o => o.nmId);

      // ---------------------------------------------------------
      // ШАГ 3: Получаем фото по nmId (Content API)
      // ---------------------------------------------------------
      // Важно: limit 100. Если заказов больше, нужно делать пагинацию (цикл)
      const contentResponse = await axios.post(
        'https://content-api.wildberries.ru/content/v2/get/cards/list',
        {
          settings: {
            cursor: { limit: 100 },
            filter: {
              withPhoto: -1, // ОБЯЗАТЕЛЬНО для получения фото
              // Можно попробовать отфильтровать, но WB часто игнорирует фильтр по nmID
              // поэтому надежнее запросить пачку и смапить на клиенте
            }
          }
        },
        { headers: { Authorization: CONTENT_TOKEN } }
      );

      const cards = contentResponse.data.cards || [];

      // ---------------------------------------------------------
      // ШАГ 4: Объединяем данные (Merge)
      // ---------------------------------------------------------
      const mergedOrders = ordersData.map(order => {
        // Ищем карточку, соответствующую nmId заказа
        const matchingCard = cards.find(card => card.nmID === order.nmId);

        // Берем фото. Обычно самое большое - в 'big', маленькое - 'tm'
        const photoUrl = matchingCard?.photos?.?.big || matchingCard?.photos?.?.tm || null;

        return {
          id: order.id,           // ID сборочного задания
          nmId: order.nmId,       // Артикул WB
          article: order.article, // Ваш артикул
          photo: photoUrl,        // Ссылка на фото
          rid: order.rid
        };
      });

      setOrders(mergedOrders);

    } catch (err) {
      console.error(err);
      setError('Ошибка загрузки данных. Проверьте консоль и CORS.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSupplyData();
  }, []);

  if (loading) return <div>Загрузка поставки...</div>;
  if (error) return <div style={{color: 'red'}}>{error}</div>;

  return (
    <div style={{ padding: 20 }}>
      <h2>Поставка: {SUPPLY_ID}</h2>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 20 }}>
        {orders.map(order => (
          <div key={order.id} style={{ border: '1px solid #ccc', padding: 10, borderRadius: 8 }}>
            <div style={{ height: 200, background: '#f0f0f0', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 10 }}>
              {order.photo ? (
                <img 
                  src={order.photo} 
                  alt={order.article} 
                  style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain' }} 
                />
              ) : (
                <span>Нет фото</span>
              )}
            </div>
            <div><strong>Арт:</strong> {order.article}</div>
            <div><strong>nmID:</strong> {order.nmId}</div>
            <div style={{ fontSize: '0.8em', color: '#666' }}>ID: {order.id}</div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default WbSupplyScanner;
