      <div className="bg-white p-8 rounded-full shadow-2xl mb-8 animate-pop-in">
        {isSuccess ? (
          <CheckCircle2 className="w-24 h-24 text-emerald-600" />
        ) : (
          <XCircle className="w-24 h-24 text-rose-600" />
        )}
