                  >
                    {isDemo ? 'РЕЖИМ ДЕМО: ВКЛЮЧЕН' : 'Включить демо режим'}
                  </button>
                </div>
              </form>
           </div>
        </div>
      )}

      {/* --- WORKSPACE SCREEN --- */}
      {orders.length > 0 && (
