const app = express();
const PORT = process.env.PORT || 3000;

app.use(express.json());

// --- DATABASE CONFIGURATION ---
const supabaseUrl = process.env.SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_KEY;
const hasSupabase = !!(supabaseUrl && supabaseKey);

let supabase = null;
if (hasSupabase) {
