// --- IN-MEMORY FALLBACK STORE ---
const memoryStore = {
    orders: new Map(), // id -> { id, status, scanned_kiz, synced_to_wb }
    content: new Map() // nmId -> { title, brand, imageUrl, sizes }
};

// --- HELPER FUNCTIONS ---

