function getBasketHost(nmId) {
    const vol = Math.floor(nmId / 100000);
    const hosts = [
        { r: 143, h: 'basket-01.wbbasket.ru' },
        { r: 287, h: 'basket-02.wbbasket.ru' },
        { r: 431, h: 'basket-03.wbbasket.ru' },
