        { r: 1169, h: 'basket-08.wbbasket.ru' },
        { r: 1313, h: 'basket-09.wbbasket.ru' },
        { r: 1601, h: 'basket-10.wbbasket.ru' },
        { r: 1655, h: 'basket-11.wbbasket.ru' },
